{
  "objective": "Using validation-only evidence, produce bounded research and risk directives for the frozen Phase 12 protocol.",
  "mode": "dry_run",
  "rationale": "The plan inspects and validates the dataset, discovers available markets and symbols, creates a validation-only split, validates the experiment configuration for the frozen protocol, estimates compute budget, evaluates a frozen checkpoint on validation data, and generates a report with risk directives. All steps operate exclusively within the validation partition and never access test metrics, satisfying the validation-only constraint.",
  "validation_only": true,
  "test_metrics_accessed": false,
  "safe_to_execute": false,
  "confidence": 0.9,
  "estimated_compute_units": 0.0,
  "steps": [
    {
      "id": "inspect_dataset",
      "action": "inspect_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      }
    },
    {
      "id": "validate_dataset",
      "action": "validate_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["inspect_dataset"]
    },
    {
      "id": "list_markets",
      "action": "list_markets",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["validate_dataset"]
    },
    {
      "id": "list_symbols",
      "action": "list_symbols",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["validate_dataset"]
    },
    {
      "id": "create_validation_split",
      "action": "create_split",
      "arguments": {
        "split_name": "validation_only",
        "partition": "validation",
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["list_markets", "list_symbols"]
    },
    {
      "id": "validate_experiment_config",
      "action": "validate_experiment_config",
      "arguments": {
        "config_path": "configs/phase12_frozen.yaml"
      },
      "depends_on": ["create_validation_split"]
    },
    {
      "id": "estimate_compute_budget",
      "action": "estimate_compute_budget",
      "arguments": {
        "config_path": "configs/phase12_frozen.yaml",
        "split_name": "validation_only"
      },
      "depends_on": ["validate_experiment_config"]
    },
    {
      "id": "evaluate_frozen_checkpoint",
      "action": "evaluate_checkpoint",
      "arguments": {
        "checkpoint_path": "checkpoints/phase12_frozen.pt",
        "split_name": "validation_only"
      },
      "depends_on": ["estimate_compute_budget"]
    },
    {
      "id": "generate_risk_directives",
      "action": "generate_report",
      "arguments": {
        "report_type": "risk_directives",
        "evaluation_results": "{{evaluate_frozen_checkpoint.artifacts}}"
      },
      "depends_on": ["evaluate_frozen_checkpoint"],
      "expected_artifacts": ["risk_directives_report.pdf"]
    }
  ]
}
